import {createTenderWorkspace} from './tender-workspace.js';
import {ensureTender} from './tender-core.js';
import {createDirectAIClient} from './calculator-direct-ai.js?v=20261102-tender';
import {GUIDES,PREPARATION_KINDS,isUncertainAnswer,preparationFor,preparationText} from './intake-guide.js';
import {connectionState,friendlyConnectionError} from './calculator-connection.js';
import {INSTALLATION_PRODUCTS,INSTALLATION_CATALOG_VERSION,mergeInstallationCatalog,filterCatalog} from './installation-catalog.js';
import {FIELDS,CATEGORIES,DEFAULT_SETTINGS,CATALOG,money,cents,id,newProject,known,completeness,phase,nextField,invalidate,setField,confirmFields,calculate,releaseIssues,localReply,generateDocuments,parseCSV,validateProject,nextIntakeField,deferQuestion,upsertPreparation,resolvePreparation} from './calculator-core.js?v=20261102-tender';
const $=s=>document.querySelector(s), e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='vr-offertewerkplaats-v1';let tab='gesprek',busy=false,noticeTimer,ai=false,aiStatus='Nog niet verbonden',consent=false,providerTested=false,catalogSearch='',catalogGroup='';
let vault={projects:[newProject()],active:'',catalog:structuredClone(CATALOG),defaults:{...DEFAULT_SETTINGS},catalogPacks:[INSTALLATION_CATALOG_VERSION]};
vault.active=vault.projects[0].id;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&Array.isArray(saved.projects)&&saved.projects.length){for(const p of saved.projects)validateProject(p);if(!Array.isArray(saved.catalog)||saved.catalog.length>500)throw Error();for(const c of saved.catalog)calculate([{...c,qty:1}],{...DEFAULT_SETTINGS});vault=saved;if(!vault.projects.some(p=>p.id===vault.active))vault.active=vault.projects[0].id;}}catch{setTimeout(()=>notice('Opgeslagen gegevens konden niet worden gelezen. De lege werkruimte is geopend.'),200);}
if(!Array.isArray(vault.catalogPacks)||!vault.catalogPacks.includes(INSTALLATION_CATALOG_VERSION)){
 try{vault.catalog=mergeInstallationCatalog(vault.catalog);vault.catalogPacks=[...(Array.isArray(vault.catalogPacks)?vault.catalogPacks:[]),INSTALLATION_CATALOG_VERSION];localStorage.setItem(KEY,JSON.stringify(vault));}
 catch(err){setTimeout(()=>notice(err.message),200);}
}
const project=()=>vault.projects.find(p=>p.id===vault.active);
const tenderWorkspace=createTenderWorkspace({isTender:()=>project()?.flow==='tender',render,notice,persist,invalidate,setBusy:value=>{busy=value;},busy:()=>busy,aiReady:()=>providerTested,analyze:data=>aiMode==='direct'?directAI.analyzeTender(data):request('/calculator/tender','POST',data),dialog:showDialog,download,catalog:()=>vault.catalog,configure:()=>{tab='configuratie';render();}});
const apiBase=(window.VR_CONFIG?.apiBase||'').replace(/\/$/,'');
const directAI=createDirectAIClient();let aiMode=apiBase?'server':'direct',directModel='',pendingDirectKey='';
aiStatus=aiMode==='direct'?'Persoonlijke test vanaf GitHub Pages. Vul jouw eigen OpenAI API sleutel en model in en kies AI verbinding testen.':connectionState(apiBase,sessionStorage.getItem('vr-session')||'').message;
addEventListener('pagehide',()=>{directAI.clear();pendingDirectKey='';if($('#direct-api-key'))$('#direct-api-key').value='';ai=false;providerTested=false;});
addEventListener('pageshow',ev=>{if(ev.persisted){aiStatus='De sleutel is gewist na het verlaten van de pagina. Verbind opnieuw om AI te gebruiken.';render();}});
for(const p of vault.projects){p.preparation ||= [];p.intakeFollowup ||= null;}
function notice(text){$('#notice').textContent=text;$('#notice').className='show';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').className='',6000);}
function persist(){project().updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(vault));$('.save-status')?.replaceChildren(document.createTextNode('Opgeslagen in deze browser'));}catch{notice('Opslaan in de browser mislukt. Exporteer je project om werk te bewaren.');}}
function greeting(p){if(!p.messages.length){p.messages.push({role:'assistant',phase:'Frontoffice',text:'Welkom bij de offertewerkplaats. Ik verzamel eerst je wensen. Daarna werken we de opdracht, kosten en uitvoering uit.\n\n'+FIELDS[0].question});p.asked='trade';}}
function opts(obj,value){return Object.entries(obj).map(([k,label])=>`<option value="${e(k)}" ${k===value?'selected':''}>${e(label)}</option>`).join('');}
function button(label,action,kind='secondary'){return `<button class="btn ${kind}" data-action="${action}">${label}</button>`;}
function render(){
 const p=project();if(p.flow==='tender'&&['gesprek','voorbereiding'].includes(tab))tab='tender';if(p.flow!=='tender'&&tab==='tender')tab='gesprek';if(p.flow!=='tender')greeting(p);
 const titles={tender:['Van bestek naar aanbieding.','Bronstukken, specialistbeoordelingen en een controleerbare offerteopzet.'],gesprek:['Van vraag naar opdracht.','Een gericht gesprek, met de afspraken direct in beeld.'],voorbereiding:['Onbekend? Dan bereiden we het voor.','Open vragen, voorlopige aannames en een gerichte locatieopname.'],calculatie:['Elke post onderbouwd.','Persoonsuren, inkoop en projectkosten. Controleerbaar tot op de cent.'],documenten:['Van opdracht naar uitvoering.','Werk het functionele concept en de uitvoering uit. Leg aannames expliciet vast.'],configuratie:['Jouw API. Jouw rekenregels.','Stel je AI verbinding, kostprijzen en verkoopmethodiek in.']};
 $('#app').innerHTML=`<div class="layout"><aside class="side"><a class="brand" href="./index.html"><img src="./mark.svg" alt=""><span>vergunningradar<small>Offertewerkplaats</small></span></a><div class="side-section"><div class="eyebrow">Installatiebedrijf</div><nav class="side-nav" aria-label="Offertewerkplaats">${[...(p.flow==='tender'?[['tender','01','Bestek en aanbesteding']]:[['gesprek','01','Klantgesprek'],['voorbereiding','02','Voorbereiding']]),['calculatie',p.flow==='tender'?'02':'03','Calculatie'],['documenten',p.flow==='tender'?'03':'04','Ontwerp en plan'],['configuratie',p.flow==='tender'?'04':'05','Configuratie']].map(([key,n,label])=>`<button data-tab="${key}" class="${key===tab?'active':''}" ${key===tab?'aria-current="page"':''}><span class="num">${n}</span>${label}</button>`).join('')}</nav></div><a class="side-link" href="./index.html#leads">Terug naar projecten</a><div class="side-foot"><div class="eyebrow">Interne demo</div><p>Voorbereiden, controleren en offreren.</p><p class="tiny">Dossiers en kostprijzen staan in deze browser. Deze werkruimte is geen beveiligd klantportaal.</p></div></aside><main id="main" class="main"><header class="top"><div><label class="tiny" for="project-select" hidden>Project kiezen</label><select aria-label="Project kiezen" class="project-select" id="project-select">${vault.projects.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${e(x.name)}</option>`).join('')}</select><span class="mode ${ai?'ai':''}">${providerTested?'AI verbinding getest':p.flow==='tender'?'Bestektraject':'Begeleide intake'}</span></div><div><span class="save-status">Opgeslagen in deze browser</span>${button('Nieuwe opdracht','new','secondary small')}</div></header><div class="heading"><div><div class="eyebrow">Offertewerkplaats / ${e(phase(p))}</div><h1>${titles[tab][0]}</h1><p>${titles[tab][1]}</p></div><div class="actions">${button('Project exporteren','export','secondary')}${button('Offerte / PDF','quote','')}</div></div><div class="callout">${p.flow==='tender'?'Een eigen offertetraject voor TenderNed stukken, bestekken en contracten. Controleer bronverwijzingen, hoeveelheden en voorwaarden vóór vrijgave.':ai?'AI stelt dossierwijzigingen voor. Jij bevestigt de gegevens en controleert ontwerp en prijzen.':'Begeleide intake. Onbekende antwoorden leiden tot eenvoudigere vragen, aannames of opnamepunten. Voor een vrij AI gesprek controleer je de aansluiting bij Configuratie.'}</div><div id="content">${tab==='tender'?tenderWorkspace.render(p):tab==='gesprek'?conversation(p):tab==='voorbereiding'?preparation(p):tab==='calculatie'?estimate(p):tab==='documenten'?documents(p):configuration(p)}</div></main></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(busy)return;tab=b.dataset.tab;render();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 $('#project-select').onchange=ev=>{if(busy)return;vault.active=ev.target.value;persist();render();if(project().flow==='tender')tenderWorkspace.checkFiles(project());};
 if(tab==='tender')tenderWorkspace.bind(p);if(tab==='gesprek')bindConversation(p);if(tab==='voorbereiding')bindPreparation(p);if(tab==='calculatie')bindEstimate(p);if(tab==='documenten')bindDocuments(p);if(tab==='configuratie')bindConfig(p);
 if(busy){lock(true);if($('#tender-stop'))$('#tender-stop').disabled=false;}
}
function conversation(p){
 const c=completeness(p),role=phase(p);
 return `<div class="stagebar">${[['Frontoffice','Contact en eerste vraag'],['Accountmanager','Doel, omvang en afspraken'],['Calculator','Kosten, ontwerp en uitvoering']].map(([name,sub],i)=>`<div class="stage ${role===name?'active':''}"><b>0${i+1} / ${name}</b><span>${sub}</span></div>`).join('')}</div><div class="conversation"><section class="panel chat-panel"><div class="panel-head"><h3>${e(role)}</h3><span class="tag">${ai?'AI gesprek':'Vraaggestuurde demo'}</span></div><div class="chat-log" id="chat-log" role="log" aria-label="Klantgesprek">${p.messages.map(m=>`<article class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'Jij':e(m.phase||'Medewerker')}</small><div class="bubble">${e(m.text)}</div></article>`).join('')}</div><form id="chat-form" class="chat-input"><label for="message">${p.asked&&!ai?e(FIELDS.find(f=>f.id===p.asked)?.label):'Jouw bericht'}</label><textarea id="message" name="message" maxlength="4000" placeholder="Beschrijf je wensen of geef antwoord op de vraag." required></textarea>${p.asked?`<div class="chat-suggestions prep-shortcuts">${button('Aanname voorstellen','defer-assumption','secondary small')}${button('Opname voorbereiden','defer-visit','secondary small')}${button('Vraag parkeren','defer-followup','secondary small')}</div>`:''}<footer><span>${ai?(aiMode==='direct'?'Dit gesprek gaat rechtstreeks naar OpenAI met jouw eigen API sleutel.':'Opdrachtgegevens worden voor dit gesprek naar de aangesloten AI dienst gestuurd.'):'Weet je iets niet? Zeg het gerust. Dan stellen we een andere vraag of bereiden we een controle voor.'}</span><button class="btn" type="submit">Versturen</button></footer></form></section><section class="panel"><div class="panel-head"><h3>Opdrachtdossier</h3>${button('Voorbeeld laden','example','secondary small')}</div><div class="panel-body"><div class="progress-line"><span class="tiny">Bevestigde opdrachtgegevens</span><strong class="score-number">${c.score}<span class="tiny"> / 100</span></strong></div><progress class="meter" value="${c.score}" max="100" aria-label="Volledigheid opdrachtdossier"></progress><p class="hint">Doel 95 procent, met alle kritieke punten bevestigd. Dit meet volledigheid, geen technische zekerheid.</p><div class="bottom-actions">${button('Samenvatting bevestigen','confirm','small')}${button('Wijzig projectnaam','rename','secondary small')}${button('Voorbereiding ('+(p.preparation||[]).filter(x=>!x.resolved).length+')','preparation','secondary small')}</div>${FIELDS.map(f=>{const v=p.fields[f.id];return `<article class="field"><div class="field-top"><b>${e(f.label)}${f.critical?' · kritiek':''}</b><span class="tag ${v.confirmed&&known(v.value)?'ok':''}">${preparationFor(p,f.id)?e(PREPARATION_KINDS[preparationFor(p,f.id).kind]):v.confirmed&&known(v.value)?'Bevestigd':v.value?'Te bevestigen':'Open'}</span></div><p>${e(v.value||'Nog niet besproken')}</p><details><summary>Aanpassen en herkomst bekijken</summary><textarea aria-label="${e(f.label)}" data-field="${f.id}" maxlength="3000">${e(v.value)}</textarea><div class="field-buttons"><button class="btn secondary small" data-save-field="${f.id}">Vastleggen</button><label class="check tiny"><input type="checkbox" data-confirm-field="${f.id}" ${v.confirmed?'checked':''} ${!known(v.value)||preparationFor(p,f.id)?'disabled':''}>Bevestigd door klant</label></div><small class="muted">${e(v.source||'Nog geen bron')} · ${f.weight} punten</small></details></article>`;}).join('')}<p class="hint">Elke aanpassing maakt eerdere technische en financiële controles ongeldig.</p></div></section></div>`;
}
function bindConversation(p){
 $('#chat-log').scrollTop=$('#chat-log').scrollHeight;
 $('#chat-form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;const text=$('#message').value.trim();if(!text)return;const role=phase(p);p.messages.push({role:'user',text,phase:'Klant'});busy=true;render();
  try{
   let reply;
   if(ai){const payload={message:text,fields:p.fields,asked:p.asked,preparation:p.preparation||[],messages:p.messages.slice(-20).map(m=>({role:m.role,content:m.text})),phase:role};const r=aiMode==='direct'?await directAI.chat(payload):await request('/calculator/chat','POST',payload);
    const draft=structuredClone(p);
    for(const change of r.updates||[])if(FIELDS.some(f=>f.id===change.field)&&change.value.trim())setField(draft,change.field,change.value,'AI extractie, nog door klant te bevestigen');
    for(const item of r.preparation||[])upsertPreparation(draft,item.field,item.kind,item.note);
    if(isUncertainAnswer(text)&&draft.asked&&!preparationFor(draft,draft.asked))upsertPreparation(draft,draft.asked,GUIDES[draft.asked].kind,GUIDES[draft.asked].task);
    draft.asked=typeof r.next_field==='string'?r.next_field:(nextIntakeField(draft)?.id||'');Object.assign(p,draft);reply=r.reply;
   }else reply=localReply(p,text);
   p.messages.push({role:'assistant',text:reply,phase:phase(p)});
  }catch(err){p.messages.push({role:'assistant',phase:'Verbindingsmelding',text:'Dit bericht is niet verwerkt. '+friendlyConnectionError(err)+' Je kunt de begeleide intake expliciet inschakelen via Configuratie.'});}
  finally{busy=false;persist();render();$('#message')?.focus();}
 };
 document.querySelectorAll('[data-save-field]').forEach(b=>b.onclick=()=>{const key=b.dataset.saveField;setField(p,key,$(`[data-field="${key}"]`).value,'Handmatig vastgelegd');persist();render();notice('Gegeven vastgelegd. Bevestig de wijziging met de klant.');});
 document.querySelectorAll('[data-confirm-field]').forEach(b=>b.onchange=()=>{p.fields[b.dataset.confirmField].confirmed=b.checked;invalidate(p);persist();render();});
}
function preparation(p){
 const items=p.preparation||[],open=items.filter(x=>!x.resolved);
 return `<div class="callout">Deze acties horen bij de werkvoorbereiding. Een geaccepteerde aanname blijft voorlopig en telt niet als gecontroleerd opdrachtgegeven. Een locatieopname wordt hier voorbereid, niet automatisch geboekt of geprijsd.</div><section class="panel"><div class="panel-head"><h3>${open.length} ${open.length===1?'open voorbereidingspunt':'open voorbereidingspunten'}</h3>${button('Opnameplan / PDF','print-preparation','secondary small')}</div><div class="panel-body"><div class="split"><label>Opdrachtveld<select id="prep-field">${FIELDS.map(f=>`<option value="${f.id}">${e(f.label)}</option>`).join('')}</select></label><label>Actie<select id="prep-kind">${opts(PREPARATION_KINDS,'followup')}</select></label></div><label>Wat moet worden nagevraagd, aangenomen of gecontroleerd?<textarea id="prep-new-note" maxlength="3000"></textarea></label>${button('Voorbereidingspunt toevoegen','prep-add','small')}</div></section><div class="prep-grid spaced">${items.length?items.map(x=>`<section class="panel"><div class="panel-head"><h3>${e(FIELDS.find(f=>f.id===x.field)?.label||x.field)}</h3><span class="tag ${x.resolved?'ok':''}">${x.resolved?'Geverifieerd':e(PREPARATION_KINDS[x.kind])}</span></div><div class="panel-body"><label>Voorbereidingsactie<textarea data-prep-note="${x.id}" maxlength="3000">${e(x.note)}</textarea></label><div class="split"><label>Verantwoordelijke<input data-prep-owner="${x.id}" maxlength="100" value="${e(x.owner||'Installateur')}"></label><label>Gewenste datum<input data-prep-date="${x.id}" type="date" value="${e(x.date||'')}"></label></div>${x.kind==='assumption'?`<label class="check"><input data-prep-accepted="${x.id}" type="checkbox" ${x.accepted?'checked':''}>Klant accepteert dit als voorlopig uitgangspunt, nog te verifiëren.</label>`:''}<p class="hint">${x.kind==='site_visit'?'Voor de definitieve offerte, controleer dit op locatie en leg de uitkomst vast. Plan zo nodig opname-uren en reiskosten in Calculatie.':'Leg vast hoe en door wie dit punt wordt gecontroleerd vóór een definitieve offerte.'}</p><label>Gecontroleerde uitkomst<textarea data-prep-resolution="${x.id}" maxlength="3000" placeholder="Vul na navraag of opname de feitelijke uitkomst en onderbouwing in.">${e(x.resolution||'')}</textarea></label><button class="btn secondary small" data-resolve-prep="${x.id}" ${x.resolved?'disabled':''}>Uitkomst vastleggen en verifiëren</button><p class="hint">Na verificatie moet de klant het gewijzigde opdrachtgegeven nog bevestigen.</p></div></section>`).join(''):'<section class="panel"><div class="empty">Nog geen open voorbereidingspunten. De chat voegt ze toe als iets onbekend is. Je kunt zelf een punt vastleggen.</div></section>'}</div>`;
}
function bindPreparation(p){
 for(const [attr,key] of [['note','note'],['owner','owner'],['date','date']])document.querySelectorAll(`[data-prep-${attr}]`).forEach(el=>el.onchange=()=>{
  const item=p.preparation.find(x=>x.id===el.dataset['prep'+attr[0].toUpperCase()+attr.slice(1)]);if(!el.value.trim()&&key==='note'){notice('Vul een voorbereidingsactie in.');return;}
  item[key]=el.value;item.resolved=false;if(key==='note')item.accepted=false;p.fields[item.field].confirmed=false;invalidate(p);persist();render();
 });
 document.querySelectorAll('[data-prep-accepted]').forEach(el=>el.onchange=()=>{const item=p.preparation.find(x=>x.id===el.dataset.prepAccepted);item.accepted=el.checked;invalidate(p);persist();});
 document.querySelectorAll('[data-resolve-prep]').forEach(el=>el.onclick=()=>{try{resolvePreparation(p,el.dataset.resolvePrep,$(`[data-prep-resolution="${el.dataset.resolvePrep}"]`).value);persist();render();notice('Uitkomst vastgelegd. Laat de klant het gewijzigde gegeven bevestigen.');}catch(err){notice(err.message);}});
}
function catalogFilters(){
 const groups=[...new Set(vault.catalog.map(c=>c.group||'Overige artikelen'))].sort((a,b)=>a.localeCompare(b,'nl'));
 if(catalogGroup&&!groups.includes(catalogGroup))catalogGroup='';
 return `<div class="catalog-filters"><label>Zoek artikel<input id="catalog-search" type="search" placeholder="Naam, artikelcode of maat" value="${e(catalogSearch)}"></label><label>Productgroep<select id="catalog-group"><option value="">Alle productgroepen</option>${groups.map(g=>`<option value="${e(g)}" ${g===catalogGroup?'selected':''}>${e(g)}</option>`).join('')}</select></label><span class="hint" id="catalog-results"></span></div>`;
}
function catalogOptions(){return filterCatalog(vault.catalog,catalogSearch,catalogGroup).map(c=>`<option value="${e(c.id)}">${e(c.code?c.code+' · ':'')}${e(c.name)} · ${money(cents(c.cost))} / ${e(c.unit)}</option>`).join('');}
function bindCatalogFilters(){
 const refresh=()=>{const matches=filterCatalog(vault.catalog,catalogSearch,catalogGroup),ids=new Set(matches.map(c=>c.id));
  $('#catalog-results').textContent=`${matches.length} van ${vault.catalog.length} artikelen`;
  if($('#catalog-choice')){$('#catalog-choice').innerHTML=catalogOptions();document.querySelector('[data-action="add-catalog"]').disabled=!matches.length;}
  document.querySelectorAll('[data-cat]').forEach(row=>row.hidden=!ids.has(row.dataset.cat));
 };
 $('#catalog-search').oninput=ev=>{catalogSearch=ev.target.value;refresh();};$('#catalog-group').onchange=ev=>{catalogGroup=ev.target.value;refresh();};refresh();
}
function estimate(p){
 let t;try{t=calculate(p.lines,p.settings);}catch(err){return `<div class="error-box">${e(err.message)}. Controleer Configuratie.</div>`;}
 return `<div class="stats"><div class="stat"><small>Verkoop excl. btw</small><div class="value">${money(t.net)}</div><small>Na korting</small></div><div class="stat"><small>Kostprijs incl. risico</small><div class="value">${money(t.totalCost)}</div><small>Alleen zichtbaar voor installateur</small></div><div class="stat"><small>Persoonsuren</small><div class="value">${t.hours.toLocaleString('nl-NL')}</div><small>${t.days} indicatieve werkdagen, ploeg ${p.settings.crew}</small></div><div class="stat"><small>Gerealiseerde marge</small><div class="value ${t.margin<0?'warning':''}">${t.margin.toFixed(1)}%</div><small>${money(t.profit)} resultaat na korting</small></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h3>Calculatieregels</h3><span class="tag">Inkoop en interne kostprijs</span></div><div class="table-wrap"><table><thead><tr><th>Omschrijving</th><th>Kostensoort</th><th>Aantal</th><th>Eenheid</th><th>Kostprijs €</th><th>Bedrag</th><th><span aria-label="Verwijderen"></span></th></tr></thead><tbody>${p.lines.map(l=>`<tr data-line="${l.id}"><td class="name-cell"><input aria-label="Omschrijving" data-prop="name" value="${e(l.name)}" maxlength="200">${l.code?`<small class="muted">${e(l.code)}${l.priceType==='demo'?' · voorbeeldprijs':''}</small>`:''}</td><td><select aria-label="Kostensoort" data-prop="category">${opts(CATEGORIES,l.category)}</select></td><td><input type="number" min="0" max="1000000" step="0.01" aria-label="Aantal" data-prop="qty" value="${l.qty}"></td><td><input class="line-unit" aria-label="Eenheid" data-prop="unit" value="${e(l.unit)}" ${l.category==='labor'?'readonly':''}></td><td><input type="number" min="0" max="1000000" step="0.01" aria-label="Kostprijs" data-prop="cost" value="${l.cost}"></td><td class="right">${money(t.details.find(x=>x.id===l.id).amount)}</td><td><button class="row-del" data-delete="${l.id}" aria-label="Regel verwijderen">×</button></td></tr>`).join('')}</tbody></table>${!p.lines.length?'<div class="empty">Voeg onderdelen en persoonsuren toe vanuit de catalogus.<br>De chat kent jouw inkoopprijzen en montagetijden niet.</div>':''}</div><div class="panel-body">${catalogFilters()}</div><div class="table-actions"><select id="catalog-choice" aria-label="Catalogusonderdeel">${catalogOptions()}</select>${button('Toevoegen','add-catalog','small')}${button('Eigen kostenpost','add-line','secondary small')}</div><div class="panel-body"><p class="hint">De 300 voorgeladen materiaalprijzen zijn voorbeelden exclusief btw. Pas ze aan naar jouw inkoopprijzen. Personeelsregels bevatten persoonsuren en interne uurkosten. Overhead en winst worden hieronder één keer toegevoegd.</p></div></section><aside class="panel"><div class="panel-head"><h3>Opbouw verkoopprijs</h3></div><div class="panel-body">${Object.entries(t.groups).map(([k,v])=>`<div class="sumrow"><span>${CATEGORIES[k]}</span><span>${money(v)}</span></div>`).join('')}<div class="sumrow subtotal"><span>Directe kosten</span><span>${money(t.direct)}</span></div><div class="sumrow"><span>Overhead</span><span>${money(t.overhead)}</span></div><div class="sumrow"><span>Risicoreserve ${p.settings.risk}%</span><span>${money(t.risk)}</span></div><div class="sumrow subtotal"><span>Totale kostprijs</span><span>${money(t.totalCost)}</span></div><div class="sumrow"><span>Prijs voor korting</span><span>${money(t.beforeDiscount)}</span></div><div class="sumrow"><span>Korting ${p.settings.discount}%</span><span>${money(t.discount)}</span></div><div class="sumrow total"><span>Excl. btw</span><span>${money(t.net)}</span></div><div class="sumrow"><span>Btw ${p.settings.vat}%</span><span>${money(t.vat)}</span></div><div class="sumrow subtotal"><span>Incl. btw</span><span>${money(t.gross)}</span></div><p class="hint">${p.settings.profitMode==='margin'?'Marge is winst gedeeld door verkoopprijs.':'Opslag wordt berekend over de totale kostprijs.'} Risicoreserve over directe kosten plus overhead. Btw geldt voor de hele opdracht.</p>${button('Rekenregels aanpassen','config','secondary small')}<div class="approval"><h3>Offertecontrole</h3>${releaseIssues(p).length?`<ul>${releaseIssues(p).map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:'<p class="hint">Dossier compleet en beide controles vastgelegd. Gereed voor handmatige vrijgave.</p>'}</div></div></aside></div>`;
}
function bindEstimate(p){
 bindCatalogFilters();
 document.querySelectorAll('[data-line] [data-prop]').forEach(input=>input.onchange=()=>{const l=p.lines.find(x=>x.id===input.closest('[data-line]').dataset.line),key=input.dataset.prop,old={...l};l[key]=['qty','cost'].includes(key)?Number(input.value):input.value;if(key==='cost')l.priceType='eigen';if(key==='category'&&l.category==='labor')l.unit='uur';try{calculate(p.lines,p.settings);invalidate(p);persist();render();}catch(err){Object.assign(l,old);notice(err.message);render();}});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{p.lines=p.lines.filter(l=>l.id!==b.dataset.delete);invalidate(p);persist();render();});
}
function documents(p){return `<div class="panel"><div class="panel-body"><div class="split"><label>Projectnaam<input id="project-name" maxlength="200" value="${e(p.name)}"></label><label>Offertenummer<input readonly value="${e(p.settings.quotePrefix)}-${e(p.id.slice(0,8).toUpperCase())}-R${p.revision}"></label></div><label>Aannames, risico’s en nog te verifiëren punten<textarea id="assumptions" maxlength="10000" placeholder="Leg vast wat nog gemeten, gecontroleerd of door de klant besloten moet worden.">${e(p.assumptions)}</textarea></label><div class="actions">${button(p.flow==='tender'?'Naar offerteopzet specialisten':'Genereer concept uit dossier','generate','')}${button('Intern dossier / PDF','internal','secondary')}${button('Ontwerp en plan / PDF','print-plan','secondary')}</div><p class="hint">Genereren vervangt de twee teksten hieronder na bevestiging. Het concept gebruikt jouw dossier en calculatie. Het maakt geen installatieberekeningen, kabelschema’s of maatvaste tekeningen.</p></div></div><div class="document-grid spaced"><section class="panel"><div class="panel-head"><h3>Functioneel conceptontwerp</h3></div><div class="panel-body"><textarea class="doc-editor" id="design" aria-label="Conceptontwerp" maxlength="30000">${e(p.design)}</textarea></div></section><section class="panel"><div class="panel-head"><h3>Projectplan</h3></div><div class="panel-body"><textarea class="doc-editor" id="plan" aria-label="Projectplan" maxlength="30000">${e(p.plan)}</textarea></div></section></div><section class="panel spaced full"><div class="panel-body"><h3>Controles voor vrijgave</h3><label class="check"><input id="technical" type="checkbox" ${p.technicalReview?'checked':''}>Installateur heeft het ontwerp, de technische gegevens en het projectplan gecontroleerd.</label><label class="check"><input id="financial" type="checkbox" ${p.financialReview?'checked':''}>Calculator heeft aantallen, persoonsuren, actuele kostprijzen, btw en voorwaarden gecontroleerd.</label><p class="hint">Elke wijziging in dossier, calculatie, documenten of rekenregels trekt deze controles in. Vrijgave is een handmatige handeling in deze demo.</p></div></section>`;}
function bindDocuments(p){
 for(const [selector,key] of [['#project-name','name'],['#assumptions','assumptions'],['#design','design'],['#plan','plan']])$(selector).onchange=ev=>{if(key==='name'&&!ev.target.value.trim()){notice('Vul een projectnaam in.');return;}p[key]=ev.target.value;if(p.tender)p.tender.scopeReviewed=false;invalidate(p);persist();$('#technical').checked=false;$('#financial').checked=false;};
 $('#technical').onchange=ev=>{p.technicalReview=ev.target.checked;persist();};$('#financial').onchange=ev=>{p.financialReview=ev.target.checked;persist();};
}
function aiConfiguration(){
 const st=directAI.status();
 return `<section class="panel ai-settings"><div class="panel-head"><h3>AI configuratie</h3><span class="tag">${aiMode==='direct'?'Eigen test, zonder extra hosting':'Via eigen server'}</span></div><div class="panel-body"><label>Verbindingswijze<select id="ai-mode">${opts({direct:'Persoonlijke test, rechtstreeks naar OpenAI',server:'Via eigen server, voor gedeeld gebruik'},aiMode)}</select></label><div class="callout config-message" role="status">${e(aiStatus)}</div>${aiMode==='direct'?`<div class="split"><label>Jouw OpenAI API sleutel<input id="direct-api-key" aria-label="Jouw OpenAI API sleutel" type="password" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="1000" placeholder="Vul hier jouw eigen sleutel in"><span class="hint">${st.hasKey?'Sleutel aanwezig in dit tabblad. Laat leeg om dezelfde sleutel te testen.':'De sleutel blijft uitsluitend in het geheugen van dit tabblad.'}</span></label><label>OpenAI model<input id="direct-model" aria-label="OpenAI model" type="text" maxlength="100" autocomplete="off" spellcheck="false" value="${e(directModel)}" placeholder="Modelnaam uit jouw OpenAI project"><span class="hint">Gebruik een model met Responses en Structured Outputs.</span></label></div><p class="config-sub">Je test rechtstreeks vanuit deze pagina, zonder extra server of Vergunningradar account. De sleutel wordt alleen naar api.openai.com gestuurd, niet opgeslagen in GitHub, browseropslag of exports. Bij verversen, verlaten van de pagina of Sleutel wissen verdwijnt hij uit het tabbladgeheugen. Scripts en ontwikkelaarstools in dit tabblad kunnen hem tijdens gebruik bereiken. Gebruik hiervoor een aparte testsleutel, geen gedeelde productiesleutel. API gebruik en de verbindingstest vallen onder jouw OpenAI API account.</p>`:`<p class="config-sub">De server bewaart de sleutel buiten de website en controleert de accounttoegang. ${apiBase?'Het serveradres is ingesteld.':'Voor deze demo is nog geen serveradres ingesteld in web/config.js.'} De verbindingstest controleert ook de AI dienst met een bericht zonder klantgegevens.</p>`}<label class="check"><input id="ai-consent" type="checkbox" ${consent?'checked':''}>${aiMode==='direct'?'Ik wil mijn opdrachtgegevens en gespreksberichten rechtstreeks naar OpenAI sturen voor deze persoonlijke test.':'Ik wil de opdrachtgegevens voor dit gesprek via mijn server naar de AI dienst sturen.'}</label><div class="actions">${button('AI verbinding testen','connect','')}${aiMode==='direct'?button('Sleutel wissen','clear-key','secondary'):''}${button('AI uitschakelen','disconnect','secondary')}${button('Uitleg test en hosting','ai-help','secondary')}</div><p class="hint">De app voegt interne calculatieregels niet automatisch toe aan de AI input. Een mislukte verbinding schakelt niet stilzwijgend naar de begeleide intake. Voor gebruik met klanten kies je een server die de sleutel buiten hun browser houdt.</p></div></section>`;
}
function configuration(p){const s=p.settings;return `${aiConfiguration()}<form id="settings-form"><div class="config-grid"><section class="panel"><div class="panel-head"><h3>Bedrijf en offerte</h3></div><div class="panel-body"><label>Bedrijfsnaam<input name="company" required maxlength="120" value="${e(s.company)}"></label><label>Voorvoegsel offertenummer<input name="quotePrefix" required maxlength="20" value="${e(s.quotePrefix)}"></label><div class="split"><label>Geldigheid in dagen<input type="number" name="validDays" value="${s.validDays}" min="1" max="365" required></label><label>Btw percentage<input type="number" name="vat" value="${s.vat}" min="0" max="100" step="0.01" required></label></div><label>Offertevoorwaarden<textarea name="terms" maxlength="4000">${e(s.terms)}</textarea></label><p class="hint">Kies het passende btw percentage voor deze opdracht. Gemengde btw tarieven en verleggingsregelingen moeten apart worden verwerkt.</p></div></section><section class="panel"><div class="panel-head"><h3>Kosten en verkoop</h3></div><div class="panel-body"><label>Overhead toerekenen<select name="overheadMode">${opts({direct:'Percentage over directe kosten',labor:'Percentage over personeelskosten',hour:'Euro per persoonsuur',fixed:'Vast bedrag per project'},s.overheadMode)}</select></label><label>Overhead, percentage of euro<input type="number" name="overhead" value="${s.overhead}" min="0" max="10000000" step="0.01" required></label><label>Risicoreserve percentage<input type="number" name="risk" value="${s.risk}" min="0" max="100" step="0.01" required></label><label>Verkoopmethode<select name="profitMode">${opts({margin:'Doelmarge op verkoopprijs',markup:'Winstopslag op kostprijs'},s.profitMode)}</select></label><div class="split"><label>Marge of opslag %<input type="number" name="profit" value="${s.profit}" min="0" max="500" step="0.01" required></label><label>Korting %<input type="number" name="discount" value="${s.discount}" min="0" max="99" step="0.01" required></label></div><p class="hint">Voorbeeld, 1.000 euro kostprijs met 20 procent marge wordt 1.250 euro. Met 20 procent opslag wordt het 1.200 euro.</p></div></section><section class="panel"><div class="panel-head"><h3>Capaciteit</h3></div><div class="panel-body"><label>Ploeggrootte<input type="number" name="crew" value="${s.crew}" min="1" max="1000" required></label><label>Productieve uren per persoon per dag<input type="number" name="hourDay" value="${s.hourDay}" min="1" max="24" step="0.5" required></label><p class="config-sub">Werkdagen zijn een rekenindicatie op basis van persoonsuren. Afhankelijkheden, levertijden en bezetting bepaal je in het projectplan.</p><p class="hint">Startwaarden en catalogusprijzen zijn voorbeelden, geen marktprijzen. Controleer welke indirecte kosten al in je uurkostprijs zitten om dubbele overhead te voorkomen.</p><div class="bottom-actions"><button class="btn" type="submit">Rekenregels opslaan</button></div><label class="check"><input id="save-defaults" type="checkbox">Ook als standaard voor nieuwe projecten</label></div></section></div></form><section class="panel spaced"><div class="panel-head"><h3>Kostencatalogus</h3><span class="tag">${vault.catalog.length} artikelen</span></div><div class="panel-body"><p class="config-sub">300 generieke installatieproducten in 10 productgroepen, met artikelcodes en bewerkbare voorbeeldprijzen exclusief btw. Dit zijn geen actuele leveranciersprijzen. CSV kolommen, name;category;unit;cost. Optioneel code, group en priceType. Kostensoorten, labor, product, material, subcontract, equipment, project. Personeel gebruikt eenheid uur. Een import vervangt de catalogus, bestaande calculaties houden hun prijzen.</p><div class="actions">${button('Catalogus CSV','catalog-export','secondary small')}${button('300 producten aanvullen','catalog-pack','secondary small')}${button('Eigen catalogusregel','catalog-new','secondary small')}<label class="btn secondary small">CSV importeren<input id="catalog-import" type="file" accept=".csv,text/csv" hidden></label><a class="btn secondary small" href="./installatiematerialen-300.csv" download>Materiaallijst 300 CSV</a></div>${catalogFilters()}</div><div class="table-wrap"><table><thead><tr><th>Omschrijving</th><th>Soort</th><th>Eenheid</th><th>Kostprijs €</th><th></th></tr></thead><tbody>${vault.catalog.map(c=>`<tr data-cat="${c.id}"><td class="name-cell"><input data-cprop="name" aria-label="Catalogusomschrijving" value="${e(c.name)}" maxlength="200"><small class="muted">${e(c.code||'Eigen artikel')} · ${e(c.group||'Overige artikelen')}${c.priceType==='demo'?' · voorbeeldprijs':''}</small></td><td><select data-cprop="category" aria-label="Catalogus kostensoort">${opts(CATEGORIES,c.category)}</select></td><td><input data-cprop="unit" aria-label="Cataloguseenheid" value="${e(c.unit)}"></td><td><input type="number" data-cprop="cost" aria-label="Catalogus kostprijs" min="0" max="1000000" step=".01" value="${c.cost}"></td><td><button class="row-del" data-cat-delete="${c.id}" aria-label="Catalogusregel verwijderen">×</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel spaced"><div class="panel-body"><h3>Projectgegevens</h3><div class="actions">${button('Project importeren','import','secondary')}${button('Project verwijderen','delete','danger')}</div><input id="project-import" type="file" accept=".json,application/json" hidden><p class="hint">Een projectexport bevat het gesprek, klantgegevens en interne prijzen. AI sleutels en AI instellingen worden nooit aan projectexports toegevoegd.</p></div></section>`;}
function bindConfig(p){
 bindCatalogFilters();
 $('#ai-mode').onchange=ev=>{directAI.clear();tenderWorkspace.resetConsent();pendingDirectKey='';ai=false;providerTested=false;consent=false;aiMode=ev.target.value;aiStatus=aiMode==='direct'?'Vul jouw eigen API sleutel en model in om rechtstreeks vanaf GitHub Pages te testen.':connectionState(apiBase,sessionStorage.getItem('vr-session')||'').message;render();};
 if(aiMode==='direct'){
  $('#direct-api-key').value=pendingDirectKey;
  $('#direct-api-key').oninput=ev=>{pendingDirectKey=ev.target.value;ai=false;providerTested=false;};
  $('#direct-model').oninput=ev=>{directModel=ev.target.value;ai=false;providerTested=false;};
 }

 $('#settings-form').onsubmit=ev=>{ev.preventDefault();const fd=new FormData(ev.target),s={...p.settings};for(const k of Object.keys(DEFAULT_SETTINGS))s[k]=typeof DEFAULT_SETTINGS[k]==='number'?Number(fd.get(k)):String(fd.get(k));try{calculate(p.lines,s);if(s.validDays<1||s.validDays>365)throw Error('Geldigheid moet 1 tot 365 dagen zijn.');p.settings=s;if($('#save-defaults').checked)vault.defaults={...s};invalidate(p);persist();render();notice('Rekenregels opgeslagen.');}catch(err){notice(err.message);}};
 $('#ai-consent').onchange=ev=>{consent=ev.target.checked;if(!consent){ai=false;aiStatus='AI uitgeschakeld, toestemming ingetrokken.';}else if(providerTested){ai=true;aiStatus='AI dienst getest en toestemming vastgelegd. Je kunt nu een vrij gesprek voeren.';}render();};
 $('#catalog-import').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('CSV mag maximaal 1 MB zijn.');const rows=parseCSV(await f.text());showDialog('Catalogus vervangen',`<p>Je vervangt de catalogus door ${rows.length} regels. Bestaande calculaties blijven gelijk.</p>`,()=>{vault.catalog=rows;persist();render();notice('Catalogus geïmporteerd.');});}catch(err){notice(err.message);}};
 $('#project-import').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;try{if(f.size>1e6)throw Error('Projectbestand mag maximaal 1 MB zijn.');const p=validateProject(JSON.parse(await f.text()));if(vault.projects.length>=50)throw Error('Maximaal 50 lokale projecten.');vault.projects.push(p);vault.active=p.id;persist();tab=p.flow==='tender'?'tender':'gesprek';render();if(p.flow==='tender')tenderWorkspace.checkFiles(p);notice('Project geïmporteerd. Bevestigingen en controles zijn ingetrokken.');}catch(err){notice(err.message||'Import mislukt.');}};
 document.querySelectorAll('[data-cat] [data-cprop]').forEach(input=>input.onchange=()=>{const c=vault.catalog.find(x=>x.id===input.closest('[data-cat]').dataset.cat),old={...c},key=input.dataset.cprop;c[key]=key==='cost'?Number(input.value):input.value;if(key==='cost')c.priceType='eigen';if(c.category==='labor')c.unit='uur';try{if(!c.name.trim()||!c.unit.trim())throw Error('Vul een omschrijving en eenheid in.');calculate([{...c,qty:1}],p.settings);persist();render();}catch(err){Object.assign(c,old);notice(err.message);render();}});
 document.querySelectorAll('[data-cat-delete]').forEach(b=>b.onclick=()=>{vault.catalog=vault.catalog.filter(c=>c.id!==b.dataset.catDelete);persist();render();});
}
function lock(state){document.querySelectorAll('button,select,input,textarea').forEach(b=>b.disabled=state);}
async function request(path,method='GET',data){
 if(!apiBase)throw Error(connectionState(apiBase,'').message);
 const res=await fetch(apiBase+path,{method,signal:AbortSignal.timeout(path==='/calculator/tender'?110000:65000),headers:{'Content-Type':'application/json',Authorization:'Bearer '+(sessionStorage.getItem('vr-session')||'')},...(data?{body:JSON.stringify(data)}:{})});
 if(res.status===401)throw Error('De AI server vereist een geldige sessie. Log opnieuw in via Vergunningradar.');
 const r=await res.json().catch(()=>{throw Error('De server gaf geen geldig API antwoord. Controleer of het ingestelde adres naar de API verwijst.');});
 if(!res.ok)throw Error(r.error||'De aanvraag aan de AI server is niet gelukt.');return r;
}
function showDialog(title,html,handler,label='Bevestigen'){
 const d=$('#dialog');d.innerHTML=`<h2>${e(title)}</h2>${html}<div class="bottom-actions"><button class="btn secondary" id="dialog-cancel">Annuleren</button><button class="btn" id="dialog-ok">${e(label)}</button></div>`;d.showModal();$('#dialog-cancel').onclick=()=>d.close();$('#dialog-ok').onclick=async()=>{d.close();await handler();};
}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function action(key){
 if(busy)return;const p=project();
 if(key==='config'){tab='configuratie';render();}
 if(key==='preparation'){tab='voorbereiding';render();}
 if(key==='prep-add'){try{upsertPreparation(p,$('#prep-field').value,$('#prep-kind').value,$('#prep-new-note').value);persist();render();}catch(err){notice(err.message);}}
 if(key.startsWith('defer-')){try{const kind={'defer-assumption':'assumption','defer-visit':'site_visit','defer-followup':'followup'}[key],reply=deferQuestion(p,kind);p.messages.push({role:'assistant',text:reply,phase:'Werkvoorbereiding'});persist();render();}catch(err){notice(err.message);}}
 if(key==='print-preparation'){printProject(p,'preparation');}
 if(key==='ai-help'){showDialog('Testen en hosting',`<p>Voor jouw persoonlijke test kan de pagina op GitHub Pages blijven. Kies rechtstreeks naar OpenAI en vul je eigen testsleutel en model in. De sleutel blijft alleen in het geheugen van dit tabblad en is daar toegankelijk voor scripts en ontwikkelaarstools. Hij wordt niet gepubliceerd of in de projectexport opgenomen.</p><p>Voor gebruik door klanten hoort de sleutel op een afgeschermde server of serverfunctie. De bestaande serverstand blijft hiervoor beschikbaar. Je hoeft de website zelf niet te verhuizen.</p>`,()=>{},'Begrepen');}
 if(key==='new'){if(vault.projects.length>=50)return notice('Maximaal 50 lokale projecten. Exporteer en verwijder eerst oude projecten.');showDialog('Nieuw offertetraject','<label>Werkwijze<select id="new-flow"><option value="intake">Klantgesprek, wensen en voorbereiding</option><option value="tender">TenderNed, bestek of contract</option></select></label>',()=>{const n=newProject();n.settings={...vault.defaults};if($('#new-flow').value==='tender'){ensureTender(n);n.name='Nieuwe bestekopdracht';}vault.projects.push(n);vault.active=n.id;tab=n.flow==='tender'?'tender':'gesprek';persist();render();});}
 if(key==='rename')showDialog('Projectnaam',`<label>Naam<input id="new-name" maxlength="200" value="${e(p.name)}"></label>`,()=>{const name=$('#new-name').value.trim();if(name){p.name=name;invalidate(p);persist();render();}});
 if(key==='confirm'){const missing=FIELDS.filter(f=>!known(p.fields[f.id].value)||preparationFor(p,f.id));showDialog('Samenvatting bevestigen',`<p>Bevestig dat je alle ingevulde dossiergegevens met de klant hebt gecontroleerd. Open of onbekende gegevens tellen niet mee.</p><p>${missing.length?'Nog open, '+e(missing.map(f=>f.label).join(', ')):'Alle velden zijn ingevuld.'}</p>`,()=>{confirmFields(p);p.messages.push({role:'assistant',phase:phase(p),text:`De ingevulde gegevens zijn bevestigd. Het dossier is ${completeness(p).score} procent compleet. ${completeness(p).ready?'Nu kan de calculator de kosten, het conceptontwerp en het projectplan uitwerken.':'Vul de resterende punten in voordat je een offerte vrijgeeft.'}`});persist();render();});}
 if(key==='export')download(`offerteproject-${p.id.slice(0,8)}.json`,JSON.stringify(p,null,2),'application/json');
 if(key==='import')$('#project-import').click();
 if(key==='delete')showDialog('Project verwijderen',`<p>Verwijder ${e(p.name)} uit deze browser. Exporteer het project eerst als je het wilt bewaren.</p>`,()=>{vault.projects=vault.projects.filter(x=>x.id!==p.id);if(!vault.projects.length){const n=newProject();n.settings={...vault.defaults};vault.projects.push(n);}vault.active=vault.projects[0].id;persist();render();},'Verwijderen');
 if(key==='add-catalog'){const c=vault.catalog.find(x=>x.id===$('#catalog-choice').value);if(!c)return notice('Voeg eerst een catalogusregel toe.');if(p.lines.length>=500)return notice('Maximaal 500 calculatieregels.');p.lines.push({...c,id:id(),qty:1});invalidate(p);persist();render();}
 if(key==='add-line'){if(p.lines.length>=500)return notice('Maximaal 500 calculatieregels.');p.lines.push({id:id(),name:'Eigen kostenpost',category:'project',unit:'post',cost:0,qty:1});invalidate(p);persist();render();}
 if(key==='generate'&&p.flow==='tender'){tab='tender';render();notice('Gebruik de gezamenlijke offerteopzet van de specialisten bij Bestek en aanbesteding.');return;}
 if(key==='generate'){showDialog('Conceptdocumenten genereren','<p>Dit vervangt de huidige ontwerptekst en het projectplan door een concept op basis van je dossier. Technische dimensionering blijft werk voor de installateur.</p>',()=>{invalidate(p);Object.assign(p,generateDocuments(p));persist();render();});}
 if(key==='example')showDialog('Fictieve voorbeeldopdracht','<p>Er wordt een apart project toegevoegd met een kantoorrenovatie en voorbeeldprijzen. Je huidige opdracht blijft bewaard.</p>',()=>{if(vault.projects.length>=50)return notice('Maximaal 50 projecten.');loadExample();},'Voorbeeld openen');
 if(key==='quote')quoteDialog(p);
 if(key==='internal')printProject(p,'internal');
 if(key==='print-plan')printProject(p,'plan');
 if(key==='catalog-export'){const q=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('kostencatalogus.csv','\uFEFFcode;group;name;category;unit;cost;priceType\r\n'+vault.catalog.map(c=>[c.code||'',c.group||'',c.name,c.category,c.unit,String(c.cost).replace('.',','),c.priceType||'eigen'].map(q).join(';')).join('\r\n'),'text/csv');}
 if(key==='catalog-pack'){try{const before=vault.catalog.length;vault.catalog=mergeInstallationCatalog(vault.catalog);vault.catalogPacks=[...new Set([...(vault.catalogPacks||[]),INSTALLATION_CATALOG_VERSION])];persist();render();notice(`${vault.catalog.length-before} ontbrekende producten toegevoegd. Bestaande prijzen zijn behouden.`);}catch(err){notice(err.message);}}
 if(key==='catalog-new'){if(vault.catalog.length>=500)return notice('Maximaal 500 catalogusregels.');vault.catalog.push({id:id(),name:'Nieuw onderdeel',category:'material',unit:'stuk',cost:0});persist();render();}
 if(key==='disconnect'||key==='clear-key'){directAI.clear();pendingDirectKey='';ai=false;providerTested=false;aiStatus=key==='clear-key'?'De sleutel is gewist uit het geheugen. Je gebruikt nu de begeleide intake.':'AI is uitgeschakeld en de testsleutel is gewist. Je gebruikt nu de begeleide intake.';render();}
 if(key==='connect')connect();
}
async function connect(){
 if(aiMode==='direct'){
  try{directAI.configure(pendingDirectKey,directModel);pendingDirectKey='';if($('#direct-api-key'))$('#direct-api-key').value='';}
  catch(err){aiStatus=err.message;render();notice(aiStatus);return;}
  busy=true;lock(true);$('.config-message').textContent='Verbinding met OpenAI en het gekozen model controleren. Er worden geen klantgegevens meegestuurd.';
  try{await directAI.test();providerTested=true;ai=consent;aiStatus=consent?'OpenAI en het gekozen model zijn getest. Je kunt nu rechtstreeks een AI gesprek voeren.':'OpenAI en het gekozen model zijn getest. Geef hieronder toestemming om het AI gesprek te gebruiken.';notice(aiStatus);}
  catch(err){ai=false;providerTested=false;aiStatus=friendlyConnectionError(err);notice(aiStatus);}
  finally{busy=false;render();}return;
 }
 const state=connectionState(apiBase,sessionStorage.getItem('vr-session')||'');
 if(!state.ready){ai=false;providerTested=false;aiStatus=state.message;render();notice(state.message);return;}
 busy=true;lock(true);try{
  const result=await request('/calculator/capabilities');if(!result.configured)throw Error('De server is bereikbaar, maar de AI sleutel of het model is nog niet ingesteld op de server.');
  await request('/calculator/test','POST',{});providerTested=true;ai=consent;
  aiStatus=consent?'Server en AI dienst zijn getest. Je kunt nu een vrij AI gesprek voeren.':'Server en AI dienst zijn getest. Geef hieronder toestemming om opdrachtgegevens te gebruiken in het AI gesprek.';notice(aiStatus);
 }catch(err){ai=false;providerTested=false;aiStatus=friendlyConnectionError(err);notice(aiStatus);}finally{busy=false;render();}
}
function quoteDialog(p){const issues=releaseIssues(p);showDialog('Offerte voorbereiden',`<p>${issues.length?'Deze opdracht kan alleen als concept worden geëxporteerd.':'De controles zijn vastgelegd. Je kunt de offerte handmatig vrijgeven.'}</p>${issues.length?`<ul>${issues.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`:''}<p>De klantversie bevat de opdracht, verkoopbedragen, aannames en voorwaarden. Interne kostprijzen en het gesprek worden weggelaten.</p>`,()=>printProject(p,'quote',!issues.length),issues.length?'Concept afdrukken':'Offerte vrijgeven en afdrukken');}
function printProject(p,type,released=false){
 let t;try{t=calculate(p.lines,p.settings);}catch(err){return notice(err.message);}
 const date=new Date(),expiry=new Date(date);expiry.setDate(expiry.getDate()+p.settings.validDays);
 let html=`<div class="print-brand">${e(p.settings.company)}</div><h1>${type==='quote'?(released?'Offerte':'Conceptofferte'):type==='plan'?'Conceptontwerp en projectplan':type==='preparation'?'Werkvoorbereiding en opnameplan':'Intern opdrachtdossier'}</h1><p>${e(p.name)}\n${e(p.settings.quotePrefix)}-${e(p.id.slice(0,8).toUpperCase())}-R${p.revision}\nDatum ${date.toLocaleDateString('nl-NL')}</p>`;
 if(p.flow==='tender'&&type!=='preparation'){html+=`<h2>Aanbieding op basis van bestek</h2><p>${e(p.tender.offerText||'Nog niet opgesteld.')}</p><h2>Scope</h2><p>${e(p.tender.scopeText)}</p><h2>Bronstukken</h2><p>${e(p.tender.documents.map(d=>d.name+', versie '+d.version).join('\n'))}</p><p>Kenmerk ${e(p.tender.meta.reference)}. Indienen ${e(p.tender.meta.deadline)}.</p>`;}
 if(type==='preparation'){html+=`<h2>Open vragen, aannames en opnamepunten</h2><p>${e(preparationText(p)||'Geen afzonderlijke voorbereidingspunten vastgelegd.')}</p><p class="print-footer">Opnames zijn hiermee voorbereid, niet geboekt. Voorlopige aannames zijn geen vastgestelde technische feiten.</p>`;}else if(type==='quote'){
  html+=`<h2>Opdrachtgever en locatie</h2><p>${e((p.flow==='tender'?p.tender.meta.client:p.fields.customer.value)||'Nog niet ingevuld')}\n${e((p.flow==='tender'?p.tender.meta.location:p.fields.address.value)||'Nog niet ingevuld')}</p><h2>Jouw opdracht</h2><p>${e(p.fields.goal.value)}\n${e(p.flow==='tender'?p.tender.scopeText:p.fields.scope.value)}</p><h2>Uitgangspunten</h2><p>${e(p.fields.constraints.value)}</p><h2>Werkzaamheden en onderdelen</h2><table><thead><tr><th>Omschrijving</th><th>Aantal</th><th>Eenheid</th></tr></thead><tbody>${p.lines.map(l=>`<tr><td>${e(l.code?l.code+' · '+l.name:l.name)}</td><td>${l.qty}</td><td>${e(l.unit)}</td></tr>`).join('')}</tbody></table><h2>Projectprijs</h2><table><tbody><tr><td>Totaal exclusief btw${t.discount?' na korting':''}</td><td class="right">${money(t.net)}</td></tr><tr><td>Btw ${p.settings.vat}%</td><td class="right">${money(t.vat)}</td></tr><tr><td>Totaal inclusief btw</td><td class="right">${money(t.gross)}</td></tr></tbody></table><h2>Planning en oplevering</h2><p>${e(p.fields.timing.value)}\n${e(p.fields.acceptance.value)}</p><h2>Buiten de opdracht</h2><p>${e(p.fields.exclusions.value)}</p><h2>Aannames en risico’s</h2><p>${e(p.assumptions||'Nog te beoordelen.')}\n${e(preparationText(p))}</p><h2>Voorwaarden</h2><p>${e(p.fields.decision.value)}\n${e(p.settings.terms)}\nGeldig tot ${expiry.toLocaleDateString('nl-NL')}.</p><p class="print-footer">${released?'Handmatig vrijgegeven na dossiercontrole. Deze demo registreert geen digitale ondertekening.':'CONCEPT, geen vrijgegeven offerte. Open punten en technische uitwerking moeten eerst worden afgerond.'}</p>`;
 }else{
  if(type==='internal')html+=`<h2>Opdrachtgegevens</h2>${FIELDS.map(f=>`<section><h3>${e(f.label)} · ${p.fields[f.id].confirmed?'bevestigd':'open'}</h3><p>${e(p.fields[f.id].value||'Nog niet ingevuld')}</p></section>`).join('')}<h2>Interne calculatie</h2><table><thead><tr><th>Omschrijving</th><th>Aantal</th><th>Kostprijs</th><th>Bedrag</th></tr></thead><tbody>${t.details.map(l=>`<tr><td>${e(l.code?l.code+' · '+l.name:l.name)}</td><td>${l.qty} ${e(l.unit)}</td><td>${money(cents(l.cost))}</td><td>${money(l.amount)}</td></tr>`).join('')}</tbody></table><p>Directe kosten ${money(t.direct)}. Overhead ${money(t.overhead)}. Risico ${money(t.risk)}. Kostprijs ${money(t.totalCost)}. Verkoop excl. btw ${money(t.net)}. Resultaat ${money(t.profit)}.</p><h2>Open punten</h2><p>${e(releaseIssues(p).join('\n')||'Geen open vrijgavepunten.')}</p>`;
  html+=`<h2>Conceptontwerp</h2><p class="doc-text">${e(p.design||'Nog niet opgesteld.')}</p><h2>Projectplan</h2><p class="doc-text">${e(p.plan||'Nog niet opgesteld.')}</p>`;
 }
 $('#print-area').innerHTML=html;window.print();
}
function loadExample(){
 const p=newProject();p.name='Voorbeeld, verlichting kantoor';p.example=true;
 const facts={trade:'Elektrotechniek, kantoorverlichting',customer:'Voorbeeldbedrijf Noord, contactpersoon mevrouw Voorbeeld. Fictieve opdracht.',address:'Voorbeeldlocatie, kantoor Noord. Fictief adres.',building:'Kantoor, 240 m² op begane grond, blijft deels in gebruik.',goal:'Vervangen van 24 bestaande armaturen door LED verlichting met regeling per ruimte.',scope:'24 armaturen vervangen, 120 meter kabel, 1 verdeler aanpassen, oude armaturen afvoeren.',existing:'Voorbeeldopname V1, bestaande routes en verdeelinrichting beoordeeld. Dit is fictieve voorbeeldinformatie.',access:'Begane grond, plafond op 3 meter. Mobiele werkvoorziening nodig. Werk buiten kantoortijden, parkeren bij achteringang.',constraints:'Fictief opnameverslag V1 bevat controle van de verdeler en kabelroutes. Lichtberekening en definitieve componentkeuze blijven expliciet onderdeel van engineering.',timing:'Uitvoering in drie aansluitende werkdagen na akkoord op de engineering en bevestigde levering.',budget:'Budgetgrens 10.000 euro exclusief btw.',exclusions:'Geen schilderwerk of plafondherstel. Opdrachtgever zorgt voor vrije werkplekken. Bouwkundige wijzigingen uitgesloten.',acceptance:'Functionele test per ruimte, meetrapport, revisietekening en gezamenlijke oplevering met opdrachtgever.',decision:'Directeur Voorbeeldbedrijf beslist. Betaling 40 procent bij opdracht en 60 procent bij oplevering.',docs:'Fictief opnameverslag V1, ruimteoverzicht V1. Geen echte documenten beoordeeld in deze demo.'};
 for(const [k,v] of Object.entries(facts))p.fields[k]={value:v,confirmed:false,source:'Fictieve voorbeelddata, door jou te controleren'};
 p.asked='';p.lines=[['engineer',8],['werk',24],['hulp',8],['led',24],['kast',1],['kabel',120],['klein',1],['hoog',2],['rit',2],['keur',1]].map(([key,qty])=>({...CATALOG.find(c=>c.id===key),id:id(),qty}));
 p.assumptions='Voorbeeldprijzen en normuren. Definitieve lichtberekening, componentkeuze en levertijd moeten vóór uitvoering door de installateur zijn bevestigd. Geen fysieke opname uitgevoerd door deze app.';
 Object.assign(p,generateDocuments(p));p.messages=[{role:'assistant',phase:'Accountmanager',text:'Dit is een fictieve kantooropdracht. De dossiergegevens en prijzen zijn voorbeelden. Bekijk de samenvatting, controleer de uitgangspunten en bevestig daarna wat met de klant is afgesproken.'}];
 vault.projects.push(p);vault.active=p.id;tab='gesprek';persist();render();
}
